-- PT107-S1-Q24. Batch 11.
BEGIN;
DO $guard$ BEGIN IF NOT EXISTS (SELECT 1 FROM lr_questions q WHERE q.qid=$batch11$PT107-S1-Q24$batch11$ AND q.stimulus=$batch11$Automobile-emission standards are enforced through annual inspection. At those inspections cars are tested while idling; that is, standing still with their engines running. Testing devices measure the levels of various pollutants as exhaust gases leave the tail pipe.$batch11$ AND q.prompt=$batch11$Which one of the following, if true, most strongly indicates that current enforcement of automobile-emission standards might be ineffective in controlling overall pollutant levels?$batch11$ AND q.correct_choice=$batch11$C$batch11$) THEN RAISE EXCEPTION 'Question changed: PT107-S1-Q24'; END IF; END $guard$;
DO $guard$ BEGIN IF (SELECT COUNT(*) FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id WHERE q.qid=$batch11$PT107-S1-Q24$batch11$ AND e.style IN ('single','standard')) <> 0 THEN RAISE EXCEPTION 'Explanation row changed: PT107-S1-Q24'; END IF; END $guard$;
INSERT INTO lr_explanations (question_id, style) SELECT q.id, 'single' FROM lr_questions q WHERE q.qid=$batch11$PT107-S1-Q24$batch11$ AND NOT EXISTS (SELECT 1 FROM lr_explanations e WHERE e.question_id=q.id AND e.style IN ('single','standard')) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_steps (explanation_id, position, label, body) SELECT e.id, v.position, v.label, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES (0, $batch11$Conclusion$batch11$, $batch11$The question asks us to show that current enforcement might fail to control overall pollution.$batch11$), (1, $batch11$Evidence$batch11$, $batch11$Cars are tested only while idling, by measuring exhaust at the tailpipe.$batch11$), (2, $batch11$Evaluate$batch11$, $batch11$The breadcrumb is "while idling." Cars pollute mostly while driving. If passing an idle test says little about pollution on the road, or even makes it worse, enforcement could miss what matters.$batch11$), (3, $batch11$Goal$batch11$, $batch11$Show that idle testing misses, or causes, pollution while driving.$batch11$)) v(position,label,body) WHERE q.qid=$batch11$PT107-S1-Q24$batch11$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_steps s WHERE s.explanation_id=e.id) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_choice_notes (explanation_id, letter, body) SELECT e.id, v.letter, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES ($batch11$A$batch11$, $batch11$The rising cost of better technology doesn't show the tests miss pollution.$batch11$), ($batch11$B$batch11$, $batch11$Needing frequent recalibration doesn't mean the devices are inaccurate when used.$batch11$), ($batch11$C$batch11$, $batch11$Tuning a car to idle cleanly makes it pollute more at highway speed. Cars pass the test and still pollute on the road.$batch11$), ($batch11$D$batch11$, $batch11$Owners working to comply suggests enforcement has an effect, if anything.$batch11$), ($batch11$E$batch11$, $batch11$How standards treat older cars says nothing about the idle test.$batch11$)) v(letter,body) WHERE q.qid=$batch11$PT107-S1-Q24$batch11$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_choice_notes n WHERE n.explanation_id=e.id AND n.letter=v.letter) ON CONFLICT DO NOTHING;
COMMIT;
